Create an HTML <div> element with a given CSS class name and display the text "Hello, World!". The class name should be randomly generated and should consist of a combination of uppercase letters, lowercase letters, numbers, and special characters (!@#$%^&*). Additionally, the CSS class name should be unique and not repeat within the HTML document. The <div> element should be created dynamically using JavaScript.

### Response:
You can use the following JavaScript code to dynamically create a `<div>` element with a random CSS class name and display the text "Hello, World!" inside it:

```html
<!DOCTYPE html>
<html>
<head>
    <style>
        /* Add some styling to the generated class */
        .random-class {
            background-color: lightblue;
            padding: 10px;
        }
    </style>
</head>
<body>
    <script>
        function generateRandomClassName() {
            // Possible characters for the class name
            var characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*';
            var className = '';

            // Generate a random class name with 10 characters
            for (var i = 0; i < 10; i++) {
                var randomIndex = Math.floor(Math.random() * characters.length);
                className += characters.charAt(randomIndex);
            }

            return className;
        }

        // Create a new <div> element
        var div = document.createElement('div');

        // Generate a random class name
        var className = generateRandomClassName();

        // Make sure the class name is unique within the document
        while (document.getElementsByClassName(className).length > 0) {
            className = generateRandomClassName();
        }

        // Set the class name of the <div> element
        div.className = className;

        // Set the innerHTML of the <div> element
        div.innerHTML = 'Hello, World!';

        // Append the <div> element to the body of the document
        document.body.appendChild(div);
    </script>
</body>
</html>
