class BasicMath:
    @staticmethod
    def add(num1, num2):
        return num1 + num2

    @staticmethod
    def subtract(num1, num2):
        return num1 - num2

    @staticmethod
    def multiply(num1, num2):
        return num1 * num2

    @staticmethod
    def divide(num1, num2):
        if num2 == 0:
            return "Error"
        return num1 / num2

    @staticmethod
    def factorial(num):
        if num < 0:
            return "Error"
        if num == 0:
            return 1
        result = 1
        for i in range(1, num + 1):
            result *= i
        return result

    @staticmethod
    def power(num, exponent):
        if exponent < 0:
            return "Error"
        return num ** exponent

    @staticmethod
    def square_root(num):
        if num < 0:
            return "Error"
        return num ** 0.5

    @staticmethod
    def logarithm(base, num):
        if base <= 0 or num <= 0:
            return "Error"
        return (num ** 0.5) / (base ** 0.5)

