5. Implement a feature to allow the user to reset their password. This feature should prompt the user to enter their current password, and then allow them to enter and confirm a new password. The class should validate the current password before allowing the user to reset their password. Additionally, the new password should not be the same as the current password.
6. Implement a feature to track the number of failed login attempts for each user. If a user fails to login three times in a row, display a message to the user indicating that their account has been locked and they need to contact support to unlock it. Additionally, implement a feature to track the last successful login timestamp for each user.
7. Store the user credentials securely in a database or external file, and retrieve them when needed for authentication. Implement encryption and hashing techniques to secure the stored passwords.

### Response:
Here is an example implementation of a user authentication class in jQuery:

```javascript
class UserAuthentication {
  constructor() {
    this.users = [
      { username: 'admin', password: 'admin123' },
      { username: 'user1', password: 'user123' },
      { username: 'user2', password: 'pass123' }
    ];
    this.failedLoginAttempts = {};
    this.lastSuccessfulLogin = {};
  }

  validateUsername(username) {
    const regex = /^[a-zA-Z0-9]+$/;
    return regex.test(username);
  }

  validatePassword(password) {
    const regex = /^(?=.*[A-Za-z])(?=.*\d)(?=.*[!@#$%^&*()\-_=+{};:,<.>]).{8,}$/;
    return regex.test(password);
  }

  encryptPassword(password) {
    // Implement encryption logic here
    return password;
  }

  hashPassword(password) {
    // Implement hashing logic here
    return password;
  }

  authenticate(username, password) {
    const user = this.users.find(u => u.username === username);
    if (user) {
      if (this.failedLoginAttempts[username] >= 3) {
        return 'Your account has been locked. Please contact support to unlock it.';
      }

      if (this.hashPassword(password) === user.password) {
        this.failedLoginAttempts[username] = 0;
        this.lastSuccessfulLogin[username] = new Date();
        return 'Login successful.';
      }

      this.failedLoginAttempts[username] = (this.failedLoginAttempts[username] || 0) + 1;
    }

    return 'Invalid username or password.';
  }

  resetPassword(username, currentPassword, newPassword) {
    const user = this.users.find(u => u.username === username);
    if (user && this.hashPassword(currentPassword) === user.password) {
      if (currentPassword === newPassword) {
        return 'New password cannot be the same as the current password.';
      }

      user.password = this.hashPassword(newPassword);
      return 'Password reset successful.';
    }

    return 'Invalid username or password.';
  }
}

