import random
import math

class RandomGenerator:
    @staticmethod
    def generate_prime_number(lower_limit, upper_limit):
        while True:
            number = random.randint(lower_limit, upper_limit)
            if RandomGenerator.is_prime(number):
                return number

    @staticmethod
    def generate_palindrome_string(length):
        if length % 2 == 0:
            half_length = length // 2
            first_half = ''.join(random.choices('abcdefghijklmnopqrstuvwxyz', k=half_length))
            second_half = first_half[::-1]
            return first_half + second_half
        else:
            half_length = length // 2
            first_half = ''.join(random.choices('abcdefghijklmnopqrstuvwxyz', k=half_length))
            middle_char = random.choice('abcdefghijklmnopqrstuvwxyz')
            second_half = first_half[::-1]
            return first_half + middle_char + second_half

    @staticmethod
    def is_prime(number):
        if number < 2:
            return False
        for i in range(2, int(math.sqrt(number)) + 1):
            if number % i == 0:
                return False
        return True

