import java.text.DecimalFormat;

abstract class Shape {
    abstract double getPerimeter();
    abstract double getArea();
    abstract void printDetails();
    abstract void printShapeName();
}

class Circle extends Shape {
    private double radius;

    public double getRadius() {
        return radius;
    }

    public void setRadius(double radius) {
        if (radius > 0) {
            this.radius = radius;
        } else {
            System.out.println("Invalid radius value.");
        }
    }

    @Override
    double getPerimeter() {
        return 2 * Math.PI * radius;
    }

    @Override
    double getArea() {
        return Math.PI * radius * radius;
    }

    @Override
    void printDetails() {
        DecimalFormat decimalFormat = new DecimalFormat("#.##");
        printShapeName();
        System.out.println("Radius: " + decimalFormat.format(radius) +
                ", Circumference: " + decimalFormat.format(getPerimeter()) +
                ", Area: " + decimalFormat.format(getArea()));
    }

    @Override
    void printShapeName() {
        System.out.print("Circle - ");
    }
}

class Rectangle extends Shape {
    private double length;
    private double width;

    public double getLength() {
        return length;
    }

    public void setLength(double length) {
        if (length > 0) {
            this.length = length;
        } else {
            System.out.println("Invalid length value.");
        }
    }

    public double getWidth() {
        return width;
    }

    public void setWidth(double width) {
        if (width > 0) {
            this.width = width;
        } else {
            System.out.println("Invalid width value.");
        }
    }

    @Override
    double getPerimeter() {
        return 2 * length + 2 * width;
    }

    @Override
    double getArea() {
        return length * width;
    }

    @Override
    void printDetails() {
        DecimalFormat decimalFormat = new DecimalFormat("#.##");
        printShapeName();
        System.out.println("Length: " + decimalFormat.format(length) +
                ", Width: " + decimalFormat.format(width) +
                ", Perimeter: " + decimalFormat.format(getPerimeter()) +
                ", Area: " + decimalFormat.format(getArea()));
    }

    @Override
    void printShapeName() {
        System.out.print("Rectangle - ");
    }
}

class Square extends Rectangle {
    private double side;

    public double getSide() {
        return side;
    }

    public void setSide(double side) {
        if (side > 0) {
            this.side = side;
            setLength(side);
            setWidth(side);
        } else {
            System.out.println("Invalid side length value.");
        }
    }

    @Override
    void printDetails() {
        DecimalFormat decimalFormat = new DecimalFormat("#.##");
        printShapeName();
        System.out.println("Side Length: " + decimalFormat.format(side) +
                ", Perimeter: " + decimalFormat.format(getPerimeter()) +
                ", Area: " + decimalFormat.format(getArea()));
    }

    @Override
    void printShapeName() {
        System.out.print("Square - ");
    }
}

public class Main {
    public static void main(String[] args) {
        Circle circle = new Circle();
        circle.setRadius(5);
        circle.printDetails();

        Rectangle rectangle = new Rectangle();
        rectangle.setLength(4);
        rectangle.setWidth(6);
        rectangle.printDetails();

        Square square = new Square();
        square.setSide(5);
        square.printDetails();
    }
}
