<?php
// Code for validating username and password

class User {
    private $username;
    private $password;

    public function __construct($username, $password) {
        $this->username = $username;
        $this->password = $password;
    }

    public function validateUsername() {
        // Requirement 1: The username must be at least 6 characters long and no more than 20 characters long.
        if (strlen($this->username) < 6 || strlen($this->username) > 20) {
            return false;
        }

        // Requirement 2: The username must only contain alphanumeric characters (a-z, A-Z, 0-9) and underscore (_).
        if (!preg_match('/^[a-zA-Z0-9_]+$/', $this->username)) {
            return false;
        }

        return true;
    }

    public function validatePassword() {
        // Requirement 3: The password must be at least 8 characters long and no more than 30 characters long.
        if (strlen($this->password) < 8 || strlen($this->password) > 30) {
            return false;
        }

        // Requirement 4: The password must contain at least one uppercase letter, one lowercase letter, one digit, and one special character (!@#$%^&*).
        if (!preg_match('/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[!@#$%^&*])/', $this->password)) {
            return false;
        }

        // Requirement 5: The username and password cannot be the same.
        if ($this->username === $this->password) {
            return false;
        }

        // Requirement 6: The code should implement a secure hashing algorithm (e.g., bcrypt) to store the password securely.
        $hashedPassword = password_hash($this->password, PASSWORD_BCRYPT);

        // Requirement 7: The password cannot contain three consecutive characters from the username.
        $usernameLength = strlen($this->username);
        for ($i = 0; $i < $usernameLength - 2; $i++) {
            $substring = substr($this->username, $i, 3);
            if (strpos($this->password, $substring) !== false) {
                return false;
            }
        }

        // Requirement 8: The password must not be a common password from a predefined list of common passwords.
        $commonPasswords = ["password", "123456"]; // Example list of common passwords
        if (in_array($this->password, $commonPasswords)) {
            return false;
        }

        return $hashedPassword;
    }
}

// Usage example:
$username = "john123";
$password = "Password1!";

$user = new User($username, $password);
if ($user->validateUsername() && $hashedPassword = $user->validatePassword()) {
    // The username and password are valid, proceed with further actions (e.g., database storage)
} else {
    // Invalid username or password, handle the error accordingly
}
