```csharp
using System;
using System.Collections.Generic;
using System.Globalization;
using System.Text.RegularExpressions;

namespace PersonalizedGreeting
{
    class Program
    {
        static void Main(string[] args)
        {
            Console.WriteLine("Welcome to Personalized Greeting Console Application!");

            int numberOfNames = ReadNumberOfNames();

            List<string> names = ReadNames(numberOfNames);

            string language = ReadLanguage();

            string greetingTemplate = ReadGreetingTemplate();

            PrintGreetingMessages(names, language, greetingTemplate);

            Console.WriteLine("Press any key to exit.");
            Console.ReadKey();
        }

        static int ReadNumberOfNames()
        {
            int numberOfNames;
            while (true)
            {
                Console.Write("Enter the number of names you want to input: ");
                if (int.TryParse(Console.ReadLine(), out numberOfNames) && numberOfNames > 0)
                {
                    return numberOfNames;
                }
                else
                {
                    Console.WriteLine("Invalid input. Please enter a positive integer value.");
                }
            }
        }

        static List<string> ReadNames(int numberOfNames)
        {
            List<string> names = new List<string>();
            for (int i = 1; i <= numberOfNames; i++)
            {
                string name = ReadValidName(i);
                names.Add(name);
            }
            return names;
        }

        static string ReadValidName(int nameIndex)
        {
            while (true)
            {
                Console.Write($"Enter name {nameIndex}: ");
                string name = Console.ReadLine();
                if (IsValidName(name))
                {
                    return ConvertToProperCase(name);
                }
                else
                {
                    Console.WriteLine("Invalid name. Name should consist of only letters and have a length between 2 and 20 characters.");
                }
            }
        }

        static bool IsValidName(string name)
        {
            return Regex.IsMatch(name, @"^[A-Za-z]{2,20}$");
        }

        static string ConvertToProperCase(string name)
        {
            TextInfo textInfo = new CultureInfo("en-US", false).TextInfo;
            return textInfo.ToTitleCase(name.ToLower());
        }

        static string ReadLanguage()
        {
            while (true)
            {
                Console.Write("Enter the desired language (English, Spanish, French, German, Italian): ");
                string language = Console.ReadLine().Trim().ToLower();
                if (IsValidLanguage(language))
                {
                    return language;
                }
                else
                {
                    Console.WriteLine("Invalid language choice. Please enter a valid language choice.");
                }
            }
        }

        static bool IsValidLanguage(string language)
        {
            return language == "english" || language == "spanish" || language == "french" || language == "german" || language == "italian";
        }

        static string ReadGreetingTemplate()
        {
            Console.Write("Enter the custom greeting message template: ");
            return Console.ReadLine();
        }

        static void PrintGreetingMessages(List<string> names, string language, string greetingTemplate)
        {
            Console.WriteLine("\n--- Greeting Messages ---\n");

            foreach (string name in names)
            {
                string greetingMessage = GenerateGreetingMessage(name, language, greetingTemplate);
                Console.WriteLine(greetingMessage);
            }
        }

        static string GenerateGreetingMessage(string name, string language, string greetingTemplate)
        {
            string greetingMessage = greetingTemplate.Replace("{name}", name);

            if (greetingMessage.Contains("{age}"))
            {
                int age = ReadAge(name);
                greetingMessage = greetingMessage.Replace("{age}", age.ToString());
            }

            switch (language)
            {
                case "english":
                    return greetingMessage;
                case "spanish":
                    return TranslateToSpanish(greetingMessage);
                case "french":
                    return TranslateToFrench(greetingMessage);
                case "german":
                    return TranslateToGerman(greetingMessage);
                case "italian":
                    return TranslateToItalian(greetingMessage);
                default:
                    return greetingMessage;
            }
        }

        static int ReadAge(string name)
        {
            int age;
            while (true)
            {
                Console.Write($"Enter {name}'s age: ");
                if (int.TryParse(Console.ReadLine(), out age) && age >= 0)
                {
                    return age;
                }
                else
                {
                    Console.WriteLine("Invalid input. Please enter a non-negative integer value.");
                }
            }
        }

        static string TranslateToSpanish(string message)
        {
            // Translation logic for Spanish language
            return "Spanish: " + message;
        }

        static string TranslateToFrench(string message)
        {
            // Translation logic for French language
            return "French: " + message;
        }

        static string TranslateToGerman(string message)
        {
            // Translation logic for German language
            return "German: " + message;
        }

        static string TranslateToItalian(string message)
        {
            // Translation logic for Italian language
            return "Italian: " + message;
        }
    }
}
